examples.template:
MonarchWidget({{title}}, onViewAll: {}) {
    MonarchActivityTimeline(
        [
            MonarchActivityTimelineEvent(
                id: {{events.0.id}},
                actor: MonarchActivityTimelineActor({{events.0.actor}}),
                verb: {{events.0.verb}},
                object: {{events.0.object}},
                time: {{events.0.time|date}}
            ),
            MonarchActivityTimelineEvent(
                id: {{events.1.id}},
                actor: MonarchActivityTimelineActor({{events.1.actor}}, kind: {{events.1.kind|case}}),
                verb: {{events.1.verb}},
                object: {{events.1.object}},
                time: {{events.1.time|date}},
                tone: {{events.1.tone|tone}}
            ),
            MonarchActivityTimelineEvent(
                id: {{events.2.id}},
                actor: MonarchActivityTimelineActor({{events.2.actor}}),
                verb: {{events.2.verb}},
                object: {{events.2.object}},
                time: {{events.2.time|date}}
            ),
            MonarchActivityTimelineEvent(
                id: {{events.3.id}},
                actor: MonarchActivityTimelineActor({{events.3.actor}}),
                verb: {{events.3.verb}},
                object: {{events.3.object}},
                time: {{events.3.time|date}}
            ),
        ],
        isGroupedByDay: false,
        density: .compact,
        now: {{now|date}},
        labels: MonarchActivityTimelineLabels(list: {{title}})
    )
}
.environment(\.timeZone, TimeZone(identifier: {{timeZone}}) ?? .gmt)

